const RETRYABLE_STATUSES = new Set([408, 429, 500, 502, 503, 504]);
const RETRYABLE_METHODS = new Set(["GET", "HEAD", "OPTIONS", "PUT", "DELETE"]);

function hasIdempotencyKey(headers) {
  if (headers == null) {
    return false;
  }

  for (const name of Object.keys(headers)) {
    if (name.toLowerCase() === "idempotency-key") {
      return true;
    }
  }

  if (typeof headers.has === "function") {
    return headers.has("Idempotency-Key");
  }

  if (typeof headers.get === "function") {
    const value = headers.get("Idempotency-Key");
    return value !== null && value !== undefined;
  }

  return false;
}

function isRetryableMethod(options) {
  const method = String(
    options.method === undefined ? "GET" : options.method,
  ).toUpperCase();

  if (RETRYABLE_METHODS.has(method)) {
    return true;
  }

  return (
    (method === "POST" || method === "PATCH") &&
    hasIdempotencyKey(options.headers)
  );
}

function createAbortError() {
  const error = new Error("The operation was aborted");
  error.name = "AbortError";
  return error;
}

export function createResilientFetch({
  fetch,
  sleep,
  random = Math.random,
  maxAttempts = 4,
  baseDelayMs = 200,
  maxDelayMs = 5000,
}) {
  function getBackoffDelay(retryNumber) {
    const cap = Math.min(
      maxDelayMs,
      baseDelayMs * 2 ** (retryNumber - 1),
    );
    return Math.floor(random() * cap);
  }

  return async function rfetch(url, options = {}) {
    let methodCanBeRetried;

    for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
      if (options.signal?.aborted) {
        throw createAbortError();
      }

      if (attempt === 1) {
        methodCanBeRetried = isRetryableMethod(options);
      }

      let response;

      try {
        response = await fetch(url, options);
      } catch (error) {
        if (error?.name === "AbortError") {
          throw error;
        }

        if (!methodCanBeRetried || attempt >= maxAttempts) {
          throw error;
        }

        await sleep(getBackoffDelay(attempt), options.signal);
        continue;
      }

      if (response.ok === true) {
        return response;
      }

      if (!RETRYABLE_STATUSES.has(response.status)) {
        return response;
      }

      if (!methodCanBeRetried || attempt >= maxAttempts) {
        return response;
      }

      const retryAfter = response.headers.get("Retry-After");
      let delayMs;

      if (typeof retryAfter === "string" && /^\d+$/.test(retryAfter)) {
        delayMs = Number(retryAfter) * 1000;

        if (delayMs > maxDelayMs) {
          return response;
        }
      } else {
        delayMs = getBackoffDelay(attempt);
      }

      await sleep(delayMs, options.signal);
    }
  };
}
